// Extract and validate email reply information
const email = $input.item.json;

// Get email details
const from = email.from || '';
const subject = email.subject || '';
const body = email.text || email.snippet || '';
const htmlBody = email.html || '';
const messageId = email.id || '';
const threadId = email.threadId || '';
const labels = email.labelIds || [];

// Extract sender email address
const emailMatch = from.match(/<([^>]+)>/) || [null, from];
const senderEmail = emailMatch[1] || from;
const senderName = from.replace(/<[^>]+>/, '').trim().replace(/"/g, '');

// Check if this could be a reply to our campaign
// Look for Re: in subject or check if it's a thread reply
const isReply = subject.toLowerCase().startsWith('re:') || 
                subject.toLowerCase().startsWith('fwd:') ||
                (threadId && threadId !== messageId);

// Skip emails FROM ourselves
const myEmail = 'YOUR_EMAIL@gmail.com'; // Replace with your Gmail
if (senderEmail.toLowerCase() === myEmail.toLowerCase()) {
  return [];
}

// Skip if no body (empty emails)
if (!body && !htmlBody) {
  return [];
}

// Clean body text - remove HTML tags and excessive whitespace
const cleanBody = (htmlBody || body)
  .replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 2000); // Limit to 2000 chars for AI

console.log(`Processing email from: ${senderEmail}, subject: ${subject}`);

return [{
  json: {
    message_id: messageId,
    thread_id: threadId,
    sender_email: senderEmail.toLowerCase().trim(),
    sender_name: senderName,
    subject,
    body_clean: cleanBody,
    is_reply: isReply,
    received_at: new Date().toISOString()
  }
}];

// Combine email data with lead data from Airtable
const emailData = $('Extract Email Info').item.json;
const searchResults = $input.all();

// Check if we found a matching lead
const leadFound = searchResults.length > 0 && searchResults[0].json.id !== undefined;

if (!leadFound) {
  return [{ json: { ...emailData, lead_found: false } }];
}

const lead = searchResults[0].json;
const fields = lead.fields || lead;

return [{
  json: {
    ...emailData,
    lead_found: true,
    record_id: lead.id,
    lead_name: fields.Name || '',
    lead_company: fields.Company || '',
    lead_title: fields.Title || '',
    lead_status: fields.Status || '',
    lead_thread_id: fields.Email_Thread_ID || ''
  }
}];

// Prepare intent classification prompt
const data = $json;

const classificationPrompt = `Phân tích email reply sau và phân loại ý định của người gửi.

Ngữ cảnh: Đây là reply của lead cho một chiến dịch cold email B2B.

Thông tin lead:
- Tên: ${data.lead_name}
- Công ty: ${data.lead_company}
- Chức danh: ${data.lead_title}

Email reply:
- Tiêu đề: ${data.subject}
- Nội dung: ${data.body_clean}

Hãy phân loại ý định thành CHÍNH XÁC MỘT trong 4 loại:
- "Interested" (Quan tâm): Người muốn biết thêm, muốn schedule call, hoặc rõ ràng open với offer
- "Not Interested" (Không quan tâm): Người từ chối rõ ràng, không có nhu cầu, hoặc đã có giải pháp khác
- "Wrong Person" (Nhầm người): Người nói họ không phụ trách, chuyển tiếp cho người khác, hoặc yêu cầu liên hệ người khác
- "On Leave" (Đang nghỉ): Auto-reply khi nghỉ phép, hoặc người nói đang nghỉ/bận

Trả về CHÍNH XÁC JSON sau (không có text khác):
{
  "intent": "<một trong: Interested | Not Interested | Wrong Person | On Leave>",
  "confidence": <số từ 0-1>,
  "summary_vi": "<tóm tắt ngắn bằng tiếng Việt, 1-2 câu>",
  "next_action": "<hành động tiếp theo được khuyến nghị>",
  "is_auto_reply": <true|false>
}`;

return [{ json: { ...data, classificationPrompt } }];

// Parse AI classification response
const data = $('Prepare Classification Prompt').item.json;
const aiResponse = $input.item.json;

let classification = { 
  intent: 'Not Interested', 
  confidence: 0.5, 
  summary_vi: 'Không thể phân loại', 
  next_action: 'Review thủ công',
  is_auto_reply: false
};

try {
  const content = aiResponse.choices?.[0]?.message?.content || '{}';
  classification = JSON.parse(content);
} catch (e) {
  console.error('Failed to parse classification:', e);
}

// Normalize intent to match our CRM statuses
const intentMap = {
  'Interested': 'Replied - Interested',
  'Not Interested': 'Replied - Not Interested',
  'Wrong Person': 'Replied - Wrong Person',
  'On Leave': 'Replied - On Leave'
};

const crmStatus = intentMap[classification.intent] || 'Replied - Not Interested';

console.log(`Intent classified: ${classification.intent} (${classification.confidence}) for ${data.lead_name}`);

return [{
  json: {
    ...data,
    intent: classification.intent,
    crm_status: crmStatus,
    confidence: classification.confidence,
    summary_vi: classification.summary_vi,
    next_action: classification.next_action,
    is_auto_reply: classification.is_auto_reply || false
  }
}];
